input.command:
cd /tmp/probe-fileio && rm -rf mat && mkdir mat && cd mat
X=/workspace/executable
mk() { rm -rf t; mkdir t; cd t
  printf 'hello hello hello\n' > real.txt
  case "$1" in
    symlink) ln -s real.txt SUB;;
    hardlink) printf 'hello hello hello\n' > SUB; ln SUB other;;
    setuid) printf 'hello hello hello\n' > SUB; chmod 4755 SUB;;
    sticky) printf 'hello hello hello\n' > SUB; chmod 1755 SUB;;
    fifo) mkfifo SUB;;
    dir) mkdir SUB;;
  esac; cd ..; }
for ft in symlink hardlink setuid sticky fifo dir; do
  for fl in "" "-k" "-c" "-f" "-k -f" "-c -f"; do
    mk $ft
    if [ "$ft" = fifo ]; then (printf 'hello hello\n' > t/SUB &) ; fi
    out=$(cd t && timeout 5 $X $fl SUB 2>&1 >/dev/null); rc=$?
    printf '%-9s flags=[%-5s] rc=%-3d msg=[%s]\n' "$ft" "$fl" "$rc" "$out"
  done
  echo "--"
done
